def run_texas_upload_reminder(force=False):
    reminder_date = datetime.now().date().isoformat()
    if texas_pnl_uploaded_for_date(reminder_date):
        return {"sent": 0, "failed": 0, "skipped": 0, "pnl_uploaded": True, "message": "P&L is already uploaded for today."}
    recipients = active_texas_upload_reminder_recipients()
    subject = f"Texas Ops P&L upload needed for {reminder_date}"
    body = (
        f"Reminder: the Texas Operations weekly P&L has not been uploaded for {reminder_date}.\n\n"
        "Please upload the P&L report in the Company Dashboard under Texas Ops before end of day.\n"
    )
    result = {"sent": 0, "failed": 0, "skipped": 0, "pnl_uploaded": False, "message": ""}
    for recipient in recipients:
        email = str(recipient["username"] or "").strip()
        if "@" not in email:
            result["skipped"] += 1
            if force:
                log_texas_upload_reminder(reminder_date, email or f"user:{recipient['id']}", subject, "skipped", "Username is not an email address.")
            continue
        if not force and texas_upload_reminder_already_attempted(reminder_date, email):
            result["skipped"] += 1
            continue
        try:
            send_email(email, subject, body)
            log_texas_upload_reminder(reminder_date, email, subject, "sent")
            result["sent"] += 1
        except Exception as exc:
            log_texas_upload_reminder(reminder_date, email, subject, "failed", exc)
            result["failed"] += 1
    result["message"] = f"Sent {result['sent']}, failed {result['failed']}, skipped {result['skipped']}."
    return result


def run_po_untouched_reminder(force=False):
    settings = po_untouched_reminder_settings()
    reminder_date = datetime.now().date().isoformat()
    pos = untouched_purchase_orders(settings["untouched_days"])
    if not pos:
        return {"sent": 0, "failed": 0, "skipped": 0, "po_count": 0, "message": "No untouched POs are currently past the alert window."}
    recipients = active_po_untouched_reminder_recipients()
    subject = f"Untouched POs need follow-up: {len(pos)}"
    po_lines = []
    for po in pos[:200]:
        label = " / ".join(str(x or "").strip() for x in [po.get("po_number"), po.get("job_number"), po.get("job_label")] if str(x or "").strip())
        po_lines.append(
            f"- {label} | status: {po.get('status') or ''} | vendor: {po.get('vendor') or ''} | created by: {po.get('requested_by_username') or ''} | last touched: {po.get('last_touched_at') or po.get('created_at') or ''}"
        )
    body = (
        f"PO follow-up reminder for {reminder_date}\n\n"
        f"The following POs have not had a pickup ticket uploaded or been closed/voided after {settings['untouched_days']} day(s):\n\n"
        + "\n".join(po_lines)
        + "\n\nPlease review Office PO Review in the Company Dashboard."
    )
    result = {"sent": 0, "failed": 0, "skipped": 0, "po_count": len(pos), "message": ""}
    for recipient in recipients:
        email = str(recipient["username"] or "").strip()
        if "@" not in email:
            result["skipped"] += 1
            if force:
                log_po_untouched_reminder(reminder_date, email or f"user:{recipient['id']}", subject, "skipped", "Username is not an email address.", len(pos))
            continue
        if not force and po_untouched_reminder_already_attempted(reminder_date, email):
            result["skipped"] += 1
            continue
        try:
            send_email(email, subject, body)
            log_po_untouched_reminder(reminder_date, email, subject, "sent", "", len(pos))
            result["sent"] += 1
        except Exception as exc:
            log_po_untouched_reminder(reminder_date, email, subject, "failed", exc, len(pos))
            result["failed"] += 1
    result["message"] = f"Found {len(pos)} untouched PO(s). Sent {result['sent']}, failed {result['failed']}, skipped {result['skipped']}."
    return result


def run_billing_invoice_reminder(force=False):
    settings = billing_invoice_reminder_settings()
    reminder_date = datetime.now().date().isoformat()
    jobs = jobs_missing_recent_customer_invoice(settings["lookback_days"])
    if not jobs:
        return {"sent": 0, "failed": 0, "skipped": 0, "job_count": 0, "message": "All active jobs have a customer invoice added inside the lookback window."}
    recipients = active_billing_invoice_reminder_recipients()
    subject = f"Jobs missing recent customer invoices: {len(jobs)}"
    job_lines = []
    for job in jobs[:200]:
        label = " / ".join(str(x or "").strip() for x in [job.get("job_number"), job.get("reference_code")] if str(x or "").strip())
        last_added = job.get("last_invoice_added_at") or "Never"
        job_lines.append(f"- {label} | {job.get('customer') or ''} | {job.get('project_name') or ''} | {job.get('job_type') or ''} | last added: {last_added}")
    body = (
        f"Customer invoice reminder for {reminder_date}\n\n"
        f"The following active jobs have not had a customer invoice added in the last {settings['lookback_days']} day(s):\n\n"
        + "\n".join(job_lines)
        + "\n\nPlease review Customer Billing in the Company Dashboard."
    )
    result = {"sent": 0, "failed": 0, "skipped": 0, "job_count": len(jobs), "message": ""}
    for recipient in recipients:
        email = str(recipient["username"] or "").strip()
        if "@" not in email:
            result["skipped"] += 1
            if force:
                log_billing_invoice_reminder(reminder_date, email or f"user:{recipient['id']}", subject, "skipped", "Username is not an email address.", len(jobs))
            continue
        if not force and billing_invoice_reminder_already_attempted(reminder_date, email):
            result["skipped"] += 1
            continue
        try:
            send_email(email, subject, body)
            log_billing_invoice_reminder(reminder_date, email, subject, "sent", "", len(jobs))
            result["sent"] += 1
        except Exception as exc:
            log_billing_invoice_reminder(reminder_date, email, subject, "failed", exc, len(jobs))
            result["failed"] += 1
    result["message"] = f"Found {len(jobs)} job(s). Sent {result['sent']}, failed {result['failed']}, skipped {result['skipped']}."
    return result


def texas_upload_reminder_scheduler():
    while True:
        try:
            now = datetime.now()
            settings = texas_upload_reminder_settings()
            reminder_hour, reminder_minute = [int(x) for x in settings["reminder_time"].split(":", 1)]
            is_due_day = now.weekday() == int(settings["weekday"])
            is_due_time = now.hour > reminder_hour or (now.hour == reminder_hour and now.minute >= reminder_minute)
            if int(settings.get("enabled") or 0) and is_due_day and is_due_time:
                run_texas_upload_reminder(force=False)
            billing_settings = billing_invoice_reminder_settings()
            billing_hour, billing_minute = [int(x) for x in billing_settings["reminder_time"].split(":", 1)]
            billing_due_day = now.weekday() == int(billing_settings["weekday"])
            billing_due_time = now.hour > billing_hour or (now.hour == billing_hour and now.minute >= billing_minute)
            if int(billing_settings.get("enabled") or 0) and billing_due_day and billing_due_time:
                run_billing_invoice_reminder(force=False)
            po_settings = po_untouched_reminder_settings()
            po_hour, po_minute = [int(x) for x in po_settings["reminder_time"].split(":", 1)]
            po_due_day = now.weekday() == int(po_settings["weekday"])
            po_due_time = now.hour > po_hour or (now.hour == po_hour and now.minute >= po_minute)
            if int(po_settings.get("enabled") or 0) and po_due_day and po_due_time:
                run_po_untouched_reminder(force=False)
        except Exception:
            traceback.print_exc()
        time.sleep(60)


def start_background_jobs():
    thread = threading.Thread(target=texas_upload_reminder_scheduler, daemon=True)
    thread.start()


def import_fieldwise_xlsx(path, project_id):
    if openpyxl is None:
        raise RuntimeError("openpyxl is not installed. Run this app with the bundled Codex Python or install openpyxl.")

    wb = openpyxl.load_workbook(path, data_only=True)
    header = {}
    if "Header" in wb.sheetnames:
        ws = wb["Header"]
        for row in ws.iter_rows(values_only=True):
            if row and row[0]:
                header[str(row[0]).strip()] = row[1] if len(row) > 1 else None

    if "Line Items" not in wb.sheetnames:
        raise RuntimeError("Expected a 'Line Items' sheet in the Field Wise export.")

    order_number = str(header.get("Order #") or "").strip()
    matched_subproject = None
    matched_change_order = None
    if order_number:
        matched_change_order = one(
            "SELECT id, subproject_id FROM change_orders WHERE project_id = ? AND job_number = ? ORDER BY id LIMIT 1",
            (project_id, order_number),
        )
        matched_subproject = one(
            "SELECT id FROM subprojects WHERE project_id = ? AND job_number = ?",
            (project_id, order_number),
        )
        if not matched_subproject:
            matched_subproject = one(
                """
                SELECT id FROM subprojects
                WHERE project_id = ?
                  AND code <> ''
                  AND instr(upper(?), upper(code)) > 0
                ORDER BY length(code) DESC
                LIMIT 1
                """,
                (project_id, order_number),
            )
    matched_subproject_id = matched_subproject["id"] if matched_subproject else None
    matched_change_order_id = matched_change_order["id"] if matched_change_order else None
    if matched_change_order and matched_change_order["subproject_id"]:
        matched_subproject_id = matched_change_order["subproject_id"]
    matched_subproject_is_tm = False
    if matched_subproject_id:
        sp_rate_row = one("SELECT COALESCE(pricing_type, 'Fixed') pricing_type FROM subprojects WHERE id = ?", (matched_subproject_id,))
        matched_subproject_is_tm = bool(sp_rate_row and is_tm_like_pricing(sp_rate_row["pricing_type"]))

    ws = wb["Line Items"]
    headers = [str(c.value).strip() if c.value else "" for c in ws[1]]
    index = {name: i for i, name in enumerate(headers)}
    required = ["Ticket", "Date", "Status", "Type", "Item", "Description", "Qty", "Rate", "Total"]
    missing = [h for h in required if h not in index]
    if missing:
        raise RuntimeError("Missing Field Wise columns: " + ", ".join(missing))

    source_file = Path(path).name
    count = 0
    skipped = 0
    with db() as con:
        if matched_subproject_id:
            sp_rate_row = con.execute("SELECT COALESCE(pricing_type, 'Fixed') pricing_type FROM subprojects WHERE id = ?", (matched_subproject_id,)).fetchone()
            matched_subproject_is_tm = bool(sp_rate_row and is_tm_like_pricing(sp_rate_row["pricing_type"]))
        for row in ws.iter_rows(min_row=2, values_only=True):
            if not any(row):
                continue
            date_value = row[index["Date"]]
            if isinstance(date_value, datetime):
                record_date = date_value.date().isoformat()
            else:
                record_date = str(date_value or "")
            type_value = str(row[index["Type"]] or "").strip()
            cost_type = "Labor" if "time" in type_value.lower() else "Field Ticket Material" if "material" in type_value.lower() else "Equipment" if "equipment" in type_value.lower() else type_value
            ticket = str(row[index["Ticket"]] or "")
            item = str(row[index["Item"]] or "")
            description = str(row[index["Description"]] or "")
            qty = money(row[index["Qty"]])
            sales_rate = money(row[index["Rate"]])
            sales_amount = money(row[index["Total"]])
            rate_info = raw_rate_for(cost_type, item, project_id)
            raw_rate = rate_info["raw_rate"]
            if cost_type == "Field Ticket Material":
                accrue_material = bool(matched_change_order_id or matched_subproject_is_tm)
                raw_rate = sales_rate * CO_MATERIAL_COST_FACTOR if accrue_material else 0
                amount = sales_amount * CO_MATERIAL_COST_FACTOR if accrue_material else 0
                rate_info = {
                    "source": "CO T&M material estimate at 35% margin" if matched_change_order_id else
                    "Subproject T&M material estimate at 35% margin" if matched_subproject_is_tm else
                    "Usage only - not budget cost"
                }
            else:
                amount = qty * raw_rate if raw_rate else sales_amount
            duplicate = con.execute(
                """
                SELECT id FROM cost_records
                WHERE project_id = ?
                  AND source = 'Field Wise'
                  AND ticket_or_invoice = ?
                  AND record_date = ?
                  AND cost_type = ?
                  AND item = ?
                  AND description = ?
                  AND sales_amount = ?
                LIMIT 1
                """,
                (project_id, ticket, record_date, cost_type, item, description, sales_amount),
            ).fetchone()
            if duplicate:
                skipped += 1
                continue
            con.execute(
                """
                INSERT INTO cost_records (
                  project_id, source, source_file, ticket_or_invoice, record_date, status,
                  subproject_id, change_order_id, cost_type, item, description, qty, rate, amount, sales_rate, sales_amount, raw_rate, raw_cost_source, notes, created_at
                )
                VALUES (?, 'Field Wise', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    project_id,
                    source_file,
                    ticket,
                    record_date,
                    str(row[index["Status"]] or ""),
                    matched_subproject_id,
                    matched_change_order_id,
                    cost_type,
                    item,
                    description,
                    qty,
                    raw_rate if raw_rate else sales_rate,
                    amount,
                    sales_rate,
                    sales_amount,
                    raw_rate,
                    rate_info["source"],
                    json.dumps(header, default=str),
                    datetime.now().isoformat(timespec="seconds"),
                ),
            )
            count += 1
    wb.close()
    return {"count": count, "skipped": skipped, "order_number": order_number, "matched_subproject_id": matched_subproject_id, "matched_change_order_id": matched_change_order_id}


def import_fieldwise_pdf(path, project_id):
    if pdfplumber is None:
        raise RuntimeError("PDF import needs pdfplumber, but it is not available in this Python runtime.")

    pages = []
    tables = []
    with pdfplumber.open(path) as pdf:
        for page_number, page in enumerate(pdf.pages, start=1):
            pages.append(page.extract_text() or "")
            for table in page.extract_tables() or []:
                tables.append((page_number, table))
    text = "\n".join(pages).strip()
    if not text:
        raise RuntimeError("No readable text was found in this PDF. It may be a scanned image PDF.")

    def table_value(label):
        for _, table in tables:
            for row in table:
                if row and len(row) > 1 and str(row[0] or "").strip().lower() == label.lower():
                    return str(row[1] or "").strip()
        return ""

    job_text = table_value("Job #") or first_regex([r"Job\s*#\s+(.+)"], text)
    order_number = first_regex([r"^([A-Za-z0-9\-]+)"], job_text, flags=0)
    master_order_number = first_regex([r"Master\s+Job\s+Order\s+(?:for\s+this\s+project\s+is\s+)?#?\s*([A-Za-z0-9\-]+)"], text, flags=re.IGNORECASE)
    ticket_number = first_regex([r"Field\s*Ticket\s*#\s*([A-Za-z0-9\-]+)"], text)
    record_date = table_value("Ticket Date") or first_regex([r"Ticket\s*Date\s*([0-9]{1,2}/[0-9]{1,2}/[0-9]{2,4})"], text)
    status = "Imported"

    work_description = first_regex([r"Work\s*Description\s*\n(.+?)\nLabor"], text, flags=re.IGNORECASE | re.DOTALL)
    work_description = re.sub(r"\s+", " ", work_description).strip()
    if not work_description:
        work_description = "Imported Field Wise PDF ticket"

    matched_subproject = None
    matched_change_order = None
    match_order_numbers = []
    for candidate in (order_number, master_order_number):
        if candidate and candidate not in match_order_numbers:
            match_order_numbers.append(candidate)
    for candidate_order_number in match_order_numbers:
        matched_change_order = one(
            "SELECT id, subproject_id FROM change_orders WHERE project_id = ? AND job_number = ? ORDER BY id LIMIT 1",
            (project_id, candidate_order_number),
        )
        matched_subproject = one(
            "SELECT id FROM subprojects WHERE project_id = ? AND job_number = ?",
            (project_id, candidate_order_number),
        )
        if not matched_subproject:
            matched_subproject = one(
                """
                SELECT id FROM subprojects
                WHERE project_id = ?
                  AND code <> ''
                  AND instr(upper(?), upper(code)) > 0
                ORDER BY length(code) DESC
                LIMIT 1
                """,
                (project_id, candidate_order_number),
            )
        if matched_change_order or matched_subproject:
            break
    matched_subproject_id = matched_subproject["id"] if matched_subproject else None
    matched_change_order_id = matched_change_order["id"] if matched_change_order else None
    if matched_change_order and matched_change_order["subproject_id"]:
        matched_subproject_id = matched_change_order["subproject_id"]
    matched_subproject_is_tm = False
    if matched_subproject_id:
        sp_rate_row = one("SELECT COALESCE(pricing_type, 'Fixed') pricing_type FROM subprojects WHERE id = ?", (matched_subproject_id,))
        matched_subproject_is_tm = bool(sp_rate_row and is_tm_like_pricing(sp_rate_row["pricing_type"]))

    source_file = Path(path).name
    records = []
    seen_extracted_records = set()

    def add_extracted_record(record):
        key = (
            record["cost_type"],
            record["item"],
            record["description"],
            record["qty"],
            record["rate"],
            record["amount"],
        )
        if key in seen_extracted_records:
            return
        seen_extracted_records.add(key)
        records.append(record)

    def looks_like_fieldwise_item_row(row):
        if len(row) < 5 or not row[0]:
            return False
        qty = money(row[2] if len(row) > 2 else 0)
        rate = parse_money_text(row[3] if len(row) > 3 else 0)
        amount = parse_money_text(row[4] if len(row) > 4 else 0)
        price_text = f"{row[3] if len(row) > 3 else ''} {row[4] if len(row) > 4 else ''}"
        if "$" not in price_text and not amount:
            return False
        return bool(qty or rate or amount)

    def add_fieldwise_item_row(row, page_number):
        if not looks_like_fieldwise_item_row(row):
            return
        item_name = str(row[0] or "").strip()
        is_equipment = is_equipment_item(item_name)
        add_extracted_record(
            {
                "cost_type": "Equipment" if is_equipment else "Field Ticket Material",
                "item": item_name,
                "description": str(row[1] or work_description).strip(),
                "qty": money(row[2] if len(row) > 2 else 0),
                "rate": parse_money_text(row[3] if len(row) > 3 else 0),
                "amount": parse_money_text(row[4] if len(row) > 4 else 0),
                "source_page": page_number,
            }
        )

    for page_number, table in tables:
        if not table:
            continue
        header = [str(c or "").strip().lower() for c in table[0]]
        if header == ["work type / comp item", "qty", "rate", "total"]:
            for row in table[1:]:
                if not row or not row[0]:
                    continue
                add_extracted_record(
                    {
                        "cost_type": "Labor",
                        "item": str(row[0] or "").strip(),
                        "description": work_description,
                        "qty": money(row[1] if len(row) > 1 else 0),
                        "rate": parse_money_text(row[2] if len(row) > 2 else 0),
                        "amount": parse_money_text(row[3] if len(row) > 3 else 0),
                        "source_page": page_number,
                    }
                )
        elif header[:5] == ["item", "item description", "qty", "rate", "amount"]:
            for row in table[1:]:
                add_fieldwise_item_row(row, page_number)
        elif looks_like_fieldwise_item_row(table[0]):
            for row in table:
                add_fieldwise_item_row(row, page_number)
        else:
            for row in table:
                add_fieldwise_item_row(row, page_number)

    for record in panel_shop_labor_records_from_tables(tables, work_description):
        add_extracted_record(record)
    for record in fieldwise_time_entry_labor_records_from_text(text, work_description):
        add_extracted_record(record)

    if not records:
        amount_text = first_regex([r"TOTAL\s*\$?\s*([0-9,]+\.[0-9]{2})"], text)
        records.append(
            {
                "cost_type": "Uncoded",
                "item": "PDF Field Ticket",
                "description": work_description,
                "qty": 1,
                "rate": parse_money_text(amount_text),
                "amount": parse_money_text(amount_text),
                "source_page": None,
            }
        )

    count = 0
    skipped = 0
    seen_record_counts = {}
    if records and any(record["cost_type"] != "Uncoded" for record in records):
        execute(
            """
            DELETE FROM cost_records
            WHERE project_id = ?
              AND source = 'Field Wise PDF'
              AND ticket_or_invoice = ?
              AND cost_type = 'Uncoded'
              AND item = 'PDF Field Ticket'
              AND COALESCE(amount, 0) = 0
              AND COALESCE(sales_amount, 0) = 0
            """,
            (project_id, ticket_number),
        )
    for record in records:
        rate_info = raw_rate_for(record["cost_type"], record["item"], project_id)
        sales_rate = money(record["rate"])
        sales_amount = money(record["amount"])
        raw_rate = rate_info["raw_rate"]
        if record["cost_type"] == "Field Ticket Material":
            accrue_material = bool(matched_change_order_id or matched_subproject_is_tm)
            raw_rate = sales_rate * CO_MATERIAL_COST_FACTOR if accrue_material else 0
            raw_amount = sales_amount * CO_MATERIAL_COST_FACTOR if accrue_material else 0
            rate_info = {
                "category": "",
                "raw_rate": raw_rate,
                "source": "CO T&M material estimate at 35% margin" if matched_change_order_id else
                "Subproject T&M material estimate at 35% margin" if matched_subproject_is_tm else
                "Usage only - not budget cost",
            }
        else:
            raw_amount = record["qty"] * raw_rate if raw_rate else sales_amount
        duplicate_key = (
            ticket_number,
            record["cost_type"],
            record["item"],
            record["description"][:500],
            record["qty"],
            sales_rate,
            sales_amount,
        )
        seen_record_counts[duplicate_key] = seen_record_counts.get(duplicate_key, 0) + 1
        existing_count = one(
            """
            SELECT COUNT(*) AS existing_count FROM cost_records
            WHERE project_id = ?
              AND source = 'Field Wise PDF'
              AND ticket_or_invoice = ?
              AND cost_type = ?
              AND item = ?
              AND description = ?
              AND qty = ?
              AND sales_rate = ?
              AND sales_amount = ?
            """,
            (project_id, ticket_number, record["cost_type"], record["item"], record["description"][:500], record["qty"], sales_rate, sales_amount),
        )
        if existing_count and existing_count["existing_count"] >= seen_record_counts[duplicate_key]:
            skipped += 1
            continue
        execute(
            """
            INSERT INTO cost_records (
              project_id, subproject_id, change_order_id, source, source_file, ticket_or_invoice, record_date, status,
              cost_type, item, description, qty, rate, amount, sales_rate, sales_amount, raw_rate, raw_cost_source, notes, created_at
            )
            VALUES (?, ?, ?, 'Field Wise PDF', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                project_id,
                matched_subproject_id,
                matched_change_order_id,
                source_file,
                ticket_number,
                record_date,
                status,
                record["cost_type"],
                record["item"],
                record["description"][:500],
                record["qty"],
                raw_rate if raw_rate else sales_rate,
                raw_amount,
                sales_rate,
                sales_amount,
                raw_rate,
                rate_info["source"],
                json.dumps({"job_text": job_text, "master_order_number": master_order_number, "rate_category": rate_info["category"], "source_page": record.get("source_page"), "extracted_text": text[:12000]}, default=str),
                datetime.now().isoformat(timespec="seconds"),
            ),
        )
        count += 1
    return {"count": count, "skipped": skipped, "order_number": order_number, "matched_subproject_id": matched_subproject_id, "matched_change_order_id": matched_change_order_id}


def import_vendor_invoice_pdf(path, project_id):
    if pdfplumber is None:
        raise RuntimeError("Vendor invoice PDF import needs pdfplumber, but it is not available.")
    text = extract_pdf_text(path)
    if not text:
        raise RuntimeError("No readable text was found in this vendor invoice PDF. It may need OCR or manual entry.")

    source_file = Path(path).name
    lower = text.lower()
    compact_lower = re.sub(r"\s+", "", lower)
    if "dsgsupply" in lower or "dakota supply group" in lower or "dsg truck delivery" in lower or "dsg#" in lower:
        vendor = "Dakota Supply Group"
        item_lines = []
        if ("invoicesummary" in compact_lower or "invoice summary" in lower) and "qty" in lower and "subtotal" in lower:
            invoice_number = first_regex([r"Invoice#\s*:?\s*([A-Za-z0-9.\-]+)"], text)
            invoice_date = first_regex([r"Invoice Date\s*:?\s*([0-9]{1,2}/[0-9]{1,2}/[0-9]{2,4})"], text)
            order_number = first_regex([r"PO number\s*:?\s*([A-Za-z0-9\-]+)"], text)
            total_due = parse_money_text(first_regex([r"Total\s*\n?\s*\$?([0-9,]+\.[0-9]{2})"], text))
            item_lines = parse_dsg_online_invoice_ocr(path)
            lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
            i = 0
            while not item_lines and i < len(lines):
                if i + 7 < len(lines) and re.search(r"QTY\s*Invoiced", lines[i + 2], flags=re.IGNORECASE):
                    manufacturer = lines[i]
                    description = lines[i + 1]
                    qty = first_regex([r"^([0-9.]+)$"], lines[i + 3], flags=0)
                    detail_parts = []
                    j = i + 4
                    while j < len(lines) and not re.match(r"^\$?[0-9,.]+/[A-Za-z]+$", lines[j]) and lines[j].lower() != "subtotal":
                        detail_parts.append(lines[j])
                        j += 1
                    if j + 2 < len(lines):
                        unit_price = parse_money_text(lines[j])
                        amount = parse_money_text(lines[j + 2])
                        item_lines.append({
                            "product_code": description.split()[0] if description.split() else manufacturer,
                            "description": " ".join([description] + detail_parts).strip(),
                            "qty": qty,
                            "unit_price": unit_price,
                            "amount": amount,
                        })
                        i = j + 3
                        continue
                i += 1
        else:
            header = re.search(r"INVOICE DATE\s+INVOICE NUMBER\s*\n([0-9]{1,2}/[0-9]{1,2}/[0-9]{4})\s+([A-Za-z0-9.\-]+)", text)
            invoice_date = header.group(1).strip() if header else ""
            invoice_number = header.group(2).strip() if header else ""
            order_number = first_regex([r"CUSTOMER NUMBER\s+CUSTOMER PO NUMBER.*?\n[0-9]+\s+([0-9]{3,})\s+"], text, flags=re.IGNORECASE | re.DOTALL)
            total_due = parse_money_text(first_regex([r"Amount Due\s+\$?([0-9,]+\.[0-9]{2})"], text))
            block_match = re.search(r"ORDER QTY\s+SHIP QTY\s+DESCRIPTION\s+UNIT PRICE\s+EXT PRICE\s*\n(.+?)\nONLINE BILLPAY", text, flags=re.IGNORECASE | re.DOTALL)
            if block_match:
                current = None
                for raw_line in block_match.group(1).splitlines():
                    line = raw_line.strip()
                    if not line:
                        continue
                    match = re.match(r"^([0-9.]+)\s*([A-Za-z]+)\s+([0-9.]+)\s*([A-Za-z]+)\s+(.+?)\s+([0-9,]+\.[0-9]+/[A-Za-z]+)\s+([0-9,]+\.[0-9]{2})$", line)
                    if match:
                        if current:
                            item_lines.append(current)
                        ordered_qty, ordered_unit, shipped_qty, shipped_unit, description, unit_text, extension = match.groups()
                        current = {
                            "ordered_qty": ordered_qty,
                            "ordered_unit": ordered_unit,
                            "shipped_qty": shipped_qty,
                            "shipped_unit": shipped_unit,
                            "product_code": description.split()[0] if description.split() else description,
                            "description": description,
                            "unit_text": unit_text,
                            "extension": extension,
                        }
                    elif current:
                        current["description"] += " " + line
                if current:
                    item_lines.append(current)
    elif "endress+hauser" in lower or "endress + hauser" in lower or ("endress" in lower and "hauser" in lower):
        vendor = "Endress+Hauser"
        invoice_number = first_regex([r"Number\s*:\s*([A-Za-z0-9\-]+)", r"Invoice\s+No\.?\s*([A-Za-z0-9\-]+)"], text, flags=re.IGNORECASE)
        invoice_date = date_text(first_regex([r"Billing\s+Date\s*:\s*([0-9]{1,2}/[0-9]{1,2}/[0-9]{2,4})", r"Date\s*:\s*([0-9]{1,2}/[0-9]{1,2}/[0-9]{2,4})"], text, flags=re.IGNORECASE))
        order_number = first_regex([r"Your\s+PO\s*:\s*([A-Za-z0-9\-]+)", r"Customer\s+PO\s*:\s*([A-Za-z0-9\-]+)"], text, flags=re.IGNORECASE)
        total_due = parse_money_text(first_regex([r"Total\s+Invoice\s+Amount\s+\$?\s*([0-9,]+\.[0-9]{2})", r"Total\s+Amount\s+\$?\s*([0-9,]+\.[0-9]{2})"], text, flags=re.IGNORECASE))
        item_lines = []
        lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
        for i, line in enumerate(lines):
            match = re.match(
                r"^([0-9]+)\s+([0-9.]+)\s+([A-Za-z]+)\s+([A-Za-z0-9/+\-]+)\s+([0-9,]+\.[0-9]{2})\s+([0-9,]+\.[0-9]{2})$",
                line,
            )
            if not match:
                continue
            item_no, qty, unit, order_code, unit_price, extension = match.groups()
            description_parts = []
            for follow in lines[i + 1:i + 10]:
                if re.search(r"^(Serial number|Commodity Code|Country of origin|US:|Order:|Total prices|Logistic Service|Supply Chain|Total Amount)\b", follow, flags=re.IGNORECASE):
                    break
                description_parts.append(follow)
            description = " ".join(description_parts).strip() or order_code
            item_lines.append({
                "product_code": order_code,
                "description": f"{order_code} {description}".strip(),
                "qty": qty,
                "unit_price": unit_price,
                "amount": extension,
            })

        logistic_service = parse_money_text(first_regex([r"Logistic\s+Service\s+([0-9,]+\.[0-9]{2})"], text, flags=re.IGNORECASE))
        supply_chain_surcharge = parse_money_text(first_regex([r"Supply\s+Chain\s+Sur\.?\s+([0-9,]+\.[0-9]{2})"], text, flags=re.IGNORECASE))
        if logistic_service:
            item_lines.append({"product_code": "Logistic Service", "description": "Logistic service", "qty": 1, "unit_price": logistic_service, "amount": logistic_service})
        if supply_chain_surcharge:
            item_lines.append({"product_code": "Supply Chain Surcharge", "description": "Supply chain surcharge", "qty": 1, "unit_price": supply_chain_surcharge, "amount": supply_chain_surcharge})
    elif "vega americas" in lower:
        vendor = "VEGA Americas"
        invoice_number = first_regex([r"Invoice\s+No\.\s*([A-Za-z0-9\-]+)"], text, flags=re.IGNORECASE)
        invoice_date = first_regex([r"\bDate:\s*([0-9]{1,2}/[0-9]{1,2}/[0-9]{2,4})"], text, flags=re.IGNORECASE)
        order_number = first_regex([r"Purchase Order:\s*(.+)"], text, flags=re.IGNORECASE)
        total_due = parse_money_text(first_regex([r"Sales Total USD\s+([0-9,]+\.[0-9]{2})"], text))
        item_lines = []
        current = None
        stop_prefixes = (
            "Unit Price", "Pos.", "Carried over", "Sales Total", "Shipping cost",
            "Tariff Surcharge", "Transaction Information", "Order No.", "Packing List",
            "Net Due Date", "Payment Terms", "Ship Date", "Incoterm", "Ship To Address",
            "Contact Information", "ORIGINAL", "- Page", "VEGA Americas"
        )
        for raw_line in text.splitlines():
            line = raw_line.strip()
            if not line:
                continue
            match = re.match(r"^([0-9]+)\s+([0-9.]+)\s+(.+?)\s+([0-9,]+\.[0-9]{2})\s+([0-9,]+\.[0-9]{2})$", line)
            if match:
                if current:
                    item_lines.append(current)
                position, qty, description, unit_price, extension = match.groups()
                current = {
                    "product_code": description.split()[0] if description.split() else description,
                    "description": description,
                    "qty": qty,
                    "unit_price": unit_price,
                    "amount": extension,
                }
                continue
            if current:
                if line.startswith(stop_prefixes):
                    item_lines.append(current)
                    current = None
                elif not re.search(r"^(Serial Number|Order Position|Packing List Position)", line, flags=re.IGNORECASE):
                    current["description"] += " " + line
        if current:
            item_lines.append(current)
        shipping = parse_money_text(first_regex([r"Shipping cost USD:\s*([0-9,]+\.[0-9]{2})"], text, flags=re.IGNORECASE))
        tariff = parse_money_text(first_regex([r"Tariff Surcharge USD:\s*([0-9,]+\.[0-9]{2})"], text, flags=re.IGNORECASE))
        if shipping:
            item_lines.append({"product_code": "Shipping", "description": "Shipping cost", "qty": 1, "unit_price": shipping, "amount": shipping})
        if tariff:
            item_lines.append({"product_code": "Tariff", "description": "Tariff surcharge", "qty": 1, "unit_price": tariff, "amount": tariff})
    elif "primec controls" in lower:
        vendor = "Prime Controls LLC"
        invoice_number = first_regex([r"INVOICE\s+PAGE:\s*[0-9]+\s*\n\s*([A-Za-z0-9\-]+)\s*\n\s*Invoice#"], text, flags=re.IGNORECASE)
        invoice_date = first_regex([r"Invoice#\s*\n\s*([0-9]{1,2}-[0-9]{1,2}-[0-9]{2,4})\s*\n\s*InvoiceDate"], text, flags=re.IGNORECASE)
        order_number = first_regex([r"SALESPERSON\s+.+?\s+PO\s+(.+)", r"\bFACILITY\s+(.+)"], text, flags=re.IGNORECASE)
        total_due = parse_money_text(first_regex([r"SUBTOTAL\s+([0-9,]+\.[0-9]{2})", r"INVOICETOTAL\s*\n\s*([0-9,]+\.[0-9]{2})"], text, flags=re.IGNORECASE))
        item_lines = []
        current = None
        block_match = re.search(r"Item\s+Description\s+Ordered\s+Shipped\s+UM\s+UnitPrice\s+Extension\s*\n(.+?)\nLast Page", text, flags=re.IGNORECASE | re.DOTALL)
        if block_match:
            for raw_line in block_match.group(1).splitlines():
                line = raw_line.strip()
                if not line:
                    continue
                match = re.match(r"^([A-Za-z0-9\-]+)\s+(.+?)\s+([0-9.]+)\s+([0-9.]+)\s+([A-Za-z]+)\s+([0-9,]+\.[0-9]{2})\s+([0-9,]+\.[0-9]{2})$", line)
                if match:
                    if current:
                        item_lines.append(current)
                    product_code, description, ordered_qty, shipped_qty, unit, unit_price, extension = match.groups()
                    current = {
                        "product_code": product_code,
                        "description": f"{product_code} {description}",
                        "qty": shipped_qty or ordered_qty,
                        "unit_price": unit_price,
                        "amount": extension,
                    }
                elif current:
                    current["description"] += " " + line
            if current:
                item_lines.append(current)
    elif "ced williston" in lower or "cedwilliston" in compact_lower:
        vendor = "CED Williston"
        invoice_header = re.search(r"([0-9]{3,}\s*-\s*[0-9]{3,})\s+([0-9]{2}/[0-9]{2}/[0-9]{2,4})", text)
        invoice_number = invoice_header.group(1).strip() if invoice_header else first_regex([r"\b([0-9]{3,}\s*-\s*[0-9]{3,})\b"], text)
        invoice_date = invoice_header.group(2).strip() if invoice_header else first_regex(
            [
                r"INVOICE\s+DATE\s*\n\s*([0-9]{1,2}/[0-9]{1,2}/[0-9]{2,4})",
                r"INVOICE\s+NO\.\s*\n\s*[0-9]{3,}\s*-\s*[0-9]{3,}\s*\n\s*([0-9]{1,2}/[0-9]{1,2}/[0-9]{2,4})",
                r"SHIP\s+DATE\s*\n\s*([0-9]{1,2}/[0-9]{1,2}/[0-9]{2,4})",
            ],
            text,
            flags=re.IGNORECASE,
        )
        if not invoice_date and invoice_number:
            invoice_date = first_regex([re.escape(invoice_number) + r".*?([0-9]{2}/[0-9]{2}/[0-9]{4})", re.escape(invoice_number) + r".*?([0-9]{2}/[0-9]{2}/[0-9]{2})"], text, flags=re.IGNORECASE | re.DOTALL)
        invoice_date = date_text(invoice_date)
        order_number = first_regex(
            [
                r"\b(HUNT-[0-9]+)\b",
                r"CUSTOMER\s+ORDER\s+NO\.\s*\n\s*([A-Za-z0-9\-]+)",
                r"CUSTOMERORDERNO\.\s*\n\s*([A-Za-z0-9\-]+)",
                r"JOB\s+NAME\s+CUSTOMER\s+ORDER\s+NO\.\s*\n.*?\b([A-Za-z0-9]+-[A-Za-z0-9]+)\b",
                r"CUSTOMER\s*\nORDER\s*\n.*?([A-Za-z0-9\-]+)\s*\nSALES PERSON",
                r"\bORDER\s*\n.*?([0-9]{3,})",
            ],
            text,
            flags=re.IGNORECASE | re.DOTALL,
        )
        total_due = parse_money_text(first_regex([r"TOTAL\s*DUE\s*[-=]*>?\s*([0-9,]+\.[0-9]{2})", r"TOTALDUE\s*\n?\s*([0-9,]+\.[0-9]{2})"], text, flags=re.IGNORECASE))
        if not total_due:
            money_values = [parse_money_text(value) for value in re.findall(r"\b[0-9,]+\.[0-9]{2}\b", text)]
            if money_values:
                total_due = money_values[-1]
        item_lines = []
        current = None
        stop_re = re.compile(r"^(TITLE TO|AT POINT|MERCHANDISE|A SERVICE|THIS SALE|CODE:|B -|C -|SALES TAX|SHIPPING CHARGE|TOTAL DUE)\b", re.IGNORECASE)
        for raw_line in text.splitlines():
            line = raw_line.strip()
            if not line:
                continue
            match = re.match(
                r"^T\s+([0-9.]+)\s+(.+?)\s+([0-9.]+)\s+([0-9,]+\.[0-9]{2})\s+([A-Za-z])\s+([0-9,]+\.[0-9]{2})$",
                line,
            )
            if match:
                if current:
                    item_lines.append(current)
                ordered_qty, product_description, shipped_qty, quoted_price, price_code, extension = match.groups()
                price_code = price_code.upper()
                parts = product_description.split()
                product_code = " ".join(parts[:2]) if len(parts) > 1 else product_description
                current = {
                    "product_code": product_code,
                    "description": product_description,
                    "qty": shipped_qty or ordered_qty,
                    "unit_price": (parse_money_text(extension) / money(shipped_qty or ordered_qty)) if money(shipped_qty or ordered_qty) else 0,
                    "amount": extension,
                    "ced_price_code": price_code,
                    "ced_quoted_price": quoted_price,
                }
                continue
            match = re.match(
                r"^T?\s*([0-9.]+)\s+(.+?)\s+([0-9.]+)\s+([0-9,]+\.[0-9]{2})\s+([A-Za-z])\s+([0-9,]+\.[0-9]{2})$",
                line,
            )
            if match:
                if current:
                    item_lines.append(current)
                ordered_qty, product_description, shipped_qty, quoted_price, price_code, extension = match.groups()
                parts = product_description.split()
                product_code = " ".join(parts[:2]) if len(parts) > 1 else product_description
                qty = money(shipped_qty or ordered_qty)
                amount = parse_money_text(extension)
                current = {
                    "product_code": product_code,
                    "description": product_description,
                    "qty": qty,
                    "unit_price": amount / qty if qty else parse_money_text(quoted_price),
                    "amount": amount,
                    "ced_price_code": price_code.upper(),
                    "ced_quoted_price": quoted_price,
                }
                continue
            if current and stop_re.search(line):
                item_lines.append(current)
                current = None
                break
            if current and not stop_re.search(line) and not re.search(r"^(INVOICE|QUANTITY|PRODUCT CODE|ORDERED|SOLD TO|SHIP TO|ACCOUNT NO\.|SALES PERSON)\b", line, flags=re.IGNORECASE):
                current["description"] += " " + line
        if current:
            item_lines.append(current)
        if not item_lines:
            lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
            for i, line in enumerate(lines):
                start = re.match(r"^([0-9]+)([A-Z][A-Z0-9\-]*)$", line)
                if not start or i + 3 >= len(lines):
                    continue
                ordered_qty, maker = start.groups()
                description = lines[i + 1]
                shipped_qty = money(lines[i + 2])
                unit_price = parse_money_text(lines[i + 3])
                if not shipped_qty or not unit_price:
                    continue
                product_code_tail = ""
                for later in lines[i + 4:i + 8]:
                    if re.fullmatch(r"[A-Z0-9][A-Z0-9\-]{2,}", later) and not re.fullmatch(r"[A-Z]", later):
                        product_code_tail = later
                        break
                item_lines.append({
                    "product_code": " ".join([maker, product_code_tail]).strip(),
                    "description": description,
                    "qty": shipped_qty or money(ordered_qty),
                    "unit_price": unit_price,
                    "amount": (shipped_qty or money(ordered_qty)) * unit_price,
                })
                break
    elif "border states" in lower:
        vendor = "Border States"
        invoice_number = first_regex([r"Credit\s+memo:\s*([A-Za-z0-9\-]+)", r"Invoice:\s*([A-Za-z0-9\-]+)"], text, flags=re.IGNORECASE)
        invoice_date = first_regex(
            [
                r"Credit\s+memo:\s*[A-Za-z0-9\-]+\s+Date:\s*([0-9]{1,2}/[0-9]{1,2}/[0-9]{4})",
                r"Invoice:\s*[A-Za-z0-9\-]+\s+Date:\s*([0-9]{1,2}/[0-9]{1,2}/[0-9]{4})",
            ],
            text,
            flags=re.IGNORECASE,
        )
        order_number = first_regex([r"P\.O\.#:\s*(.+)"], text, flags=re.IGNORECASE)
        total_due = parse_money_text(first_regex([r"Net Invoice Amount\s+\$\s*([0-9,]+\.[0-9]{2}-?)", r"Total\s+\$\s*([0-9,]+\.[0-9]{2}-?)"], text, flags=re.IGNORECASE))
        item_lines = []
        current = None
        for raw_line in text.splitlines():
            line = raw_line.strip()
            if not line:
                continue
            start = re.match(r"^([0-9]{6})\s+([A-Za-z0-9\-]+)\s+([0-9,]+(?:\.[0-9]+)?)$", line)
            if start:
                if current:
                    item_lines.append(current)
                line_no, material, ordered_qty = start.groups()
                current = {
                    "product_code": material,
                    "description": material,
                    "ordered_qty": ordered_qty,
                    "qty": ordered_qty,
                    "unit_price": 0,
                    "amount": 0,
                }
                continue
            if not current:
                continue
            batch = re.match(
                r"^Batch Total:\s*([0-9,]+(?:\.[0-9]+)?)\s+([A-Za-z]+)\s+([0-9,]+(?:\.[0-9]+)?)\s+([0-9,]+\.[0-9]{2}-?)\s*/\s*([0-9,]+(?:\.[0-9]+)?)\s+([A-Za-z]+)\s+([0-9,]+\.[0-9]{2}-?)$",
                line,
                flags=re.IGNORECASE,
            )
            if batch:
                batch_qty, batch_uom, ship_qty, quoted_price, price_per_qty, price_per_uom, extension = batch.groups()
                qty = parse_money_text(ship_qty or batch_qty or current.get("ordered_qty"))
                amount = parse_money_text(extension)
                current["qty"] = qty
                current["unit_price"] = amount / qty if qty else parse_money_text(quoted_price)
                current["amount"] = amount
                current["description"] = re.sub(r"\s+", " ", current["description"]).strip()
                item_lines.append(current)
                current = None
                continue
            if re.search(r"^(Cust Material #|Batch:|OD |Williston stocked)\b", line, flags=re.IGNORECASE):
                current["description"] += " " + line
            elif not re.search(r"^(INVOICE|Page |Invoice:|Cust Acct|Cash discount|Total due|Shipping and Handling|State Tax|County Tax|Local Tax|Other Tax|Tax Subtotal|Net Invoice Amount|ORIGINAL REPRINT)\b", line, flags=re.IGNORECASE):
                current["description"] += " " + line
        if current and parse_money_text(current.get("amount")):
            item_lines.append(current)
    elif "crescent electric" in lower or "crescentelectric.com" in lower:
        vendor = "Crescent Electric"
        invoice_number = first_regex(
            [
                r"INVOICE\s+DATE\s+CUSTOMER\s+NO\.\s+INVOICE\s+NO\.\s*\n\s*[0-9/]+\s+[0-9]+\s+([A-Za-z0-9.\-]+)",
                r"INVOICE\s+NUMBER\s+([A-Za-z0-9.\-]+)",
                r"\b([A-Z][0-9]{9}\.[0-9]{3})\b",
            ],
            text,
            flags=re.IGNORECASE,
        )
        invoice_date = date_text(first_regex([r"\b([0-9]{1,2}/[0-9]{1,2}/[0-9]{2})\s+[0-9]+\s+" + re.escape(invoice_number)], text, flags=re.IGNORECASE)) if invoice_number else ""
        if not invoice_date:
            invoice_date = date_text(first_regex([r"INVOICE\s+DATE\s+([0-9]{1,2}/[0-9]{1,2}/[0-9]{2,4})", r"\b([0-9]{1,2}/[0-9]{1,2}/[0-9]{2})\s+[0-9]+\s+[A-Za-z0-9.\-]+"], text, flags=re.IGNORECASE))
        order_number = first_regex(
            [
                r"ORDERED\s+BY\s+CUST\s+PO\s+ORDER\s+DATE\s+REFERENCE\s*\n.*?\s+([A-Za-z0-9\-]+)\s+[0-9]{1,2}/[0-9]{1,2}/[0-9]{2,4}",
                r"CUST\s+PO\s+([A-Za-z0-9\-]+)",
            ],
            text,
            flags=re.IGNORECASE | re.DOTALL,
        )
        total_due = parse_money_text(first_regex([r"INVOICE\s+TOTAL\s+\$?([0-9,]+\.[0-9]{2})", r"TOTAL\s+AMOUNT\s*\n?.*?\$?([0-9,]+\.[0-9]{2})"], text, flags=re.IGNORECASE | re.DOTALL))
        item_lines = []
        for raw_line in text.splitlines():
            line = raw_line.strip()
            match = re.match(r"^([0-9.]+)\s+ea\s+([0-9.]+)\s+ea\s+(.+?)\s+\$?([0-9,]+\.[0-9]{2,4})/ea\s+\$?([0-9,]+\.[0-9]{2})$", line, flags=re.IGNORECASE)
            if not match:
                continue
            ordered_qty, shipped_qty, description, unit_price, extension = match.groups()
            item_lines.append({
                "product_code": description.split()[0] if description.split() else "Crescent Item",
                "description": description,
                "qty": shipped_qty or ordered_qty,
                "unit_price": unit_price,
                "amount": extension,
            })
            break
    elif "mccody" in lower or "fromthedirtup" in lower:
        vendor = "McCody Concrete Products"
        header = re.search(
            r"DATE\s+INVOICE\s*#\s*\n(?:.*\n){0,3}?\s*([0-9]{1,2}/[0-9]{1,2}/[0-9]{2,4})\s+([A-Za-z0-9\-]+)",
            text,
            flags=re.IGNORECASE,
        )
        invoice_date = date_text(header.group(1).strip()) if header else first_regex([r"\b([0-9]{1,2}/[0-9]{1,2}/[0-9]{2,4})\b"], text)
        invoice_number = header.group(2).strip() if header else ""
        if not invoice_number:
            invoice_number = first_regex([r"Inv_([A-Za-z0-9\-]+)_from_MCCODY"], source_file, flags=re.IGNORECASE)
        order_number = first_regex([r"JOB\s*/\s*PO\s*#:\s*([A-Za-z0-9\-]+)"], text, flags=re.IGNORECASE)
        total_due = parse_money_text(first_regex([r"BALANCE\s+DUE\s+\$?([0-9,]+\.[0-9]{2})", r"TOTAL\s+\$?([0-9,]+\.[0-9]{2})"], text, flags=re.IGNORECASE))
        item_lines = []
        for raw_line in text.splitlines():
            line = raw_line.strip()
            match = re.match(r"^(.+?)\s+([0-9]+(?:\.[0-9]+)?)\s+([A-Za-z]+)\s+(.+?)\s+([0-9,]+\.[0-9]{2})\s+([0-9,]+\.[0-9]{2})T?$", line)
            if match and "SUBTOTAL" not in line.upper():
                item_name, qty, unit, item_id, unit_price, extension = match.groups()
                item_lines.append({
                    "product_code": item_id.split()[0] if item_id.split() else item_name[:40],
                    "description": item_name,
                    "qty": qty,
                    "unit_price": unit_price,
                    "amount": extension,
                })
                break
    else:
        vendor = first_regex([r"^([A-Z][A-Za-z0-9 &.\-]+)\s*\n"], text, flags=re.MULTILINE) or "Vendor"
        invoice_number = first_regex([r"Invoice\s*(?:No\.?|#)\s*:?\s*([A-Za-z0-9\-]+)"], text)
        invoice_date = first_regex([r"Invoice\s*Date\s*:?\s*([0-9]{1,2}/[0-9]{1,2}/[0-9]{2,4})"], text)
        order_number = first_regex([r"(?:PO|Purchase Order|Customer PO)(?:\s*number|\s*#)?\s*:?\s*([A-Za-z0-9\-]+)"], text)
        total_due = parse_money_text(first_regex([r"(?:Total|Amount Due)\s*:?\s*\$?\s*([0-9,]+\.[0-9]{2})"], text))
        item_lines = []

    matched_subproject = None
    if order_number:
        matched_subproject = one(
            "SELECT id FROM subprojects WHERE project_id = ? AND job_number = ?",
            (project_id, order_number),
        )
        if not matched_subproject:
            matched_subproject = one(
                """
                SELECT id FROM subprojects
                WHERE project_id = ?
                  AND code <> ''
                  AND instr(upper(?), upper(code)) > 0
                ORDER BY length(code) DESC
                LIMIT 1
                """,
                (project_id, order_number),
            )
    matched_subproject_id = matched_subproject["id"] if matched_subproject else None

    duplicate_invoice = None
    if invoice_number:
        duplicate_invoice = one(
            """
            SELECT COUNT(*) AS line_count, COALESCE(SUM(amount), 0) AS total_amount, MAX(source_file) AS source_file
            FROM cost_records
            WHERE project_id = ?
              AND source = 'Vendor Invoice'
              AND ticket_or_invoice = ?
              AND (? = '' OR vendor = ?)
            """,
            (project_id, invoice_number, vendor or "", vendor or ""),
        )
        if duplicate_invoice and duplicate_invoice["line_count"]:
            return {
                "count": 0,
                "skipped": duplicate_invoice["line_count"],
                "order_number": order_number,
                "matched_subproject_id": matched_subproject_id,
                "vendor": vendor,
                "invoice_number": invoice_number,
                "duplicate": True,
                "existing_line_count": duplicate_invoice["line_count"],
                "existing_total": duplicate_invoice["total_amount"],
                "existing_source_file": duplicate_invoice["source_file"],
            }

    count = 0
    skipped = 0
    if item_lines:
        for line in item_lines:
            if isinstance(line, dict):
                product_code = line["product_code"]
                description = line["description"]
                if "qty" in line:
                    qty = money(line["qty"])
                    amount = parse_money_text(line["amount"])
                    unit_price = parse_money_text(line.get("unit_price")) if line.get("unit_price") is not None else (amount / qty if qty else 0)
                else:
                    qty = money(line["shipped_qty"] or line["ordered_qty"])
                    amount = parse_money_text(line["extension"])
                    unit_price = amount / qty if qty else 0
            elif len(line) == 6:
                ordered_qty, product_code, description, shipped_qty, per_hundred_price, extension = line
                qty = money(shipped_qty or ordered_qty)
                amount = parse_money_text(extension)
                unit_price = amount / qty if qty else 0
            else:
                ordered_qty, product_description, shipped_qty, per_hundred_price, extension = line
                parts = product_description.split()
                product_code = " ".join(parts[:2]) if len(parts) > 1 else product_description
                description = " ".join(parts[2:]) if len(parts) > 2 else product_description
                qty = money(shipped_qty or ordered_qty)
                amount = parse_money_text(extension)
                unit_price = amount / qty if qty else 0
            execute(
                """
                INSERT INTO cost_records (
                  project_id, subproject_id, source, source_file, ticket_or_invoice, record_date, status,
                  cost_type, item, description, qty, rate, amount, sales_rate, sales_amount, raw_rate, raw_cost_source,
                  vendor, notes, created_at
                )
                VALUES (?, ?, 'Vendor Invoice', ?, ?, ?, 'Imported', 'Material', ?, ?, ?, ?, ?, 0, 0, ?, 'Vendor invoice actual material cost', ?, ?, ?)
                """,
                (
                    project_id,
                    matched_subproject_id,
                    source_file,
                    invoice_number,
                    invoice_date,
                    product_code,
                    description.strip(),
                    qty,
                    unit_price,
                    amount,
                    unit_price,
                    vendor,
                    json.dumps({"order_number": order_number, "text": text[:12000]}, default=str),
                    datetime.now().isoformat(timespec="seconds"),
                ),
            )
            count += 1
    else:
        if not total_due:
            raise RuntimeError("Could not find invoice line items or total due in this vendor invoice.")
        duplicate = one(
            "SELECT id FROM cost_records WHERE project_id = ? AND source = 'Vendor Invoice' AND source_file = ? AND ticket_or_invoice = ? LIMIT 1",
            (project_id, source_file, invoice_number),
        )
        if duplicate:
            skipped += 1
        else:
            execute(
                """
                INSERT INTO cost_records (
                  project_id, subproject_id, source, source_file, ticket_or_invoice, record_date, status,
                  cost_type, item, description, qty, rate, amount, raw_rate, raw_cost_source, vendor, notes, created_at
                )
                VALUES (?, ?, 'Vendor Invoice', ?, ?, ?, 'Imported', 'Material', 'Vendor Invoice Total', ?, 1, ?, ?, ?, 'Vendor invoice actual material cost', ?, ?, ?)
                """,
                (
                    project_id,
                    matched_subproject_id,
                    source_file,
                    invoice_number,
                    invoice_date,
                    f"{vendor} invoice total",
                    total_due,
                    total_due,
                    total_due,
                    vendor,
                    json.dumps({"order_number": order_number, "text": text[:12000]}, default=str),
                    datetime.now().isoformat(timespec="seconds"),
                ),
            )
            count += 1
    return {"count": count, "skipped": skipped, "order_number": order_number, "matched_subproject_id": matched_subproject_id, "vendor": vendor, "invoice_number": invoice_number, "duplicate": False}


def extract_vendor_invoice_total(path):
    if Path(path).suffix.lower() != ".pdf" or pdfplumber is None:
        return 0.0
    try:
        text = extract_pdf_text(path)
    except Exception:
        return 0.0
    if not text:
        return 0.0
    patterns = [
        r"INVOICE\s+TOTAL\s+\$?([0-9,]+\.[0-9]{2})",
        r"Amount Due\s+\$?([0-9,]+\.[0-9]{2})",
        r"TOTAL\s+DUE\s*[-=]*>?\s*\$?([0-9,]+\.[0-9]{2})",
        r"TOTALDUE\s*\n?\s*\$?([0-9,]+\.[0-9]{2})",
        r"INVOICETOTAL\s*\n\s*\$?([0-9,]+\.[0-9]{2})",
        r"Net Invoice Amount\s+\$\s*([0-9,]+\.[0-9]{2})",
        r"BALANCE\s+DUE\s+\$?([0-9,]+\.[0-9]{2})",
        r"Total\s+Invoice\s+Amount\s+\$?\s*([0-9,]+\.[0-9]{2})",
        r"Total\s+Amount\s+\$?\s*([0-9,]+\.[0-9]{2})",
        r"(?:Total|Amount Due)\s*:?\s*\$?\s*([0-9,]+\.[0-9]{2})",
        r"Total\s*\n?\s*\$?([0-9,]+\.[0-9]{2})",
    ]
    amount = parse_money_text(first_regex(patterns, text, flags=re.IGNORECASE))
    if amount:
        return amount
    money_values = [parse_money_text(value) for value in re.findall(r"\b[0-9,]+\.[0-9]{2}\b", text)]
    money_values = [value for value in money_values if value > 0]
    return money_values[-1] if money_values else 0.0


def sync_po_invoice_cost_record(con, po, invoice_file, actor, invoice_amount=None, cost_record_id=None):
    if not po["project_id"]:
        return None
    now = datetime.now().isoformat(timespec="seconds")
    amount = money(invoice_amount if invoice_amount is not None else po["estimated_amount"])
    notes = json.dumps(
        {
            "po_id": po["id"],
            "po_number": po["po_number"],
            "uploaded_by": actor["username"] if actor else "",
            "uploaded_at": now,
            "job_number": po["job_number"],
            "job_label": po["job_label"],
            "invoice_amount": amount,
        },
        default=str,
    )
    description = f"PO invoice {po['po_number']}: {po['description'] or ''}".strip()
    if cost_record_id:
        existing = con.execute("SELECT id FROM cost_records WHERE id = ?", (cost_record_id,)).fetchone()
        if not existing:
            cost_record_id = None
    if cost_record_id:
        con.execute(
            """
            UPDATE cost_records
            SET project_id = ?,
                subproject_id = ?,
                change_order_id = ?,
                source_file = ?,
                ticket_or_invoice = ?,
                record_date = ?,
                status = 'Imported',
                cost_type = 'Material',
                item = 'PO Invoice',
                description = ?,
                qty = 1,
                rate = ?,
                amount = ?,
                raw_rate = ?,
                raw_cost_source = 'PO invoice upload',
                vendor = ?,
                notes = ?
            WHERE id = ?
            """,
            (
                po["project_id"],
                po["subproject_id"],
                po["change_order_id"],
                invoice_file,
                po["po_number"],
                now[:10],
                description,
                amount,
                amount,
                amount,
                po["vendor"],
                notes,
                cost_record_id,
            ),
        )
        return cost_record_id
    cur = con.execute(
        """
        INSERT INTO cost_records (
          project_id, subproject_id, change_order_id, source, source_file, ticket_or_invoice,
          record_date, status, cost_type, item, description, qty, rate, amount, raw_rate,
          raw_cost_source, vendor, notes, created_at
        )
        VALUES (?, ?, ?, 'Vendor Invoice', ?, ?, ?, 'Imported', 'Material', 'PO Invoice', ?, 1, ?, ?, ?, 'PO invoice upload', ?, ?, ?)
        """,
        (
            po["project_id"],
            po["subproject_id"],
            po["change_order_id"],
            invoice_file,
            po["po_number"],
            now[:10],
            description,
            amount,
            amount,
            amount,
            po["vendor"],
            notes,
            now,
        ),
    )
    return cur.lastrowid


def purchase_orders_with_invoices(sql, params=()):
    po_rows = rows(sql, params)
    if not po_rows:
        return po_rows
    po_ids = [po["id"] for po in po_rows]
    placeholders = ",".join("?" for _ in po_ids)
    invoice_rows = rows(
        f"""
        SELECT *
        FROM purchase_order_invoices
        WHERE po_id IN ({placeholders})
        ORDER BY uploaded_at DESC, id DESC
        """,
        po_ids,
    )
    invoices_by_po = {}
    for invoice in invoice_rows:
        invoices_by_po.setdefault(invoice["po_id"], []).append(invoice)
    for po in po_rows:
        po["invoices"] = invoices_by_po.get(po["id"], [])
    return po_rows


def is_tm_like_pricing(value):
    return str(value or "Fixed") in ("T&M", "T&M NTE")


def nte_match_text_for_record(record):
    text = " ".join(str(record.get(k) or "") for k in ("item", "description")).strip()
    words = re.findall(r"[A-Za-z0-9#&/.-]+", text)
    useful = [w for w in words if len(w) > 2][:6]
    return " ".join(useful) or str(record.get("ticket_or_invoice") or "").strip()


def ensure_nte_defaults(con, project_id, subproject_id=None, change_order_id=None):
    project_id = int(project_id)
    subproject_id = int(subproject_id) if subproject_id else None
    change_order_id = int(change_order_id) if change_order_id else None
    now = datetime.now().isoformat(timespec="seconds")
    if change_order_id:
        target = con.execute(
            """
            SELECT co.co_number, co.job_number, co.title
            FROM change_orders co
            WHERE co.id = ? AND co.project_id = ?
            """,
            (change_order_id, project_id),
        ).fetchone()
        if not target:
            return None
        bucket_name = " - ".join(str(x) for x in (target["job_number"], target["co_number"], target["title"]) if x) or "NTE Scope"
        defaults = [("Labor", "Labor", 0), ("Material", "Material", 0), ("Equipment", "Equipment", 0)]
    else:
        target = con.execute("SELECT * FROM subprojects WHERE id = ? AND project_id = ?", (subproject_id, project_id)).fetchone()
        if not target:
            return None
        bucket_name = " - ".join(str(x) for x in (target["job_number"], target["code"], target["name"]) if x) or "NTE Scope"
        defaults = [
            ("Labor", "Labor", target["budget_labor"]),
            ("Material", "Material", target["budget_material"]),
            ("Equipment", "Equipment", target["budget_equipment"]),
        ]
    existing = con.execute(
        """
        SELECT id
        FROM nte_buckets
        WHERE project_id = ?
          AND COALESCE(subproject_id, 0) = COALESCE(?, 0)
          AND COALESCE(change_order_id, 0) = COALESCE(?, 0)
        LIMIT 1
        """,
        (project_id, subproject_id, change_order_id),
    ).fetchone()
    if existing:
        con.execute("UPDATE nte_buckets SET name = ?, updated_at = ? WHERE id = ?", (bucket_name, now, existing["id"]))
        return existing["id"]
    cur = con.execute(
        """
        INSERT INTO nte_buckets (project_id, subproject_id, change_order_id, name, description, sort_order, active, created_at, updated_at)
        VALUES (?, ?, ?, ?, 'Seeded from job setup; edit these buckets as the NTE scope changes.', 10, 1, ?, ?)
        """,
        (project_id, subproject_id, change_order_id, bucket_name, now, now),
    )
    bucket_id = cur.lastrowid
    for idx, (name, cost_type, budget) in enumerate(defaults, start=1):
        con.execute(
            """
            INSERT INTO nte_subbuckets (bucket_id, name, cost_type, original_budget, labor_hours_budget, sort_order, active, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, 1, ?, ?)
            """,
            (bucket_id, name, cost_type, money(budget), money(target["budget_labor_hours"]) if not change_order_id and cost_type == "Labor" else 0, idx * 10, now, now),
        )
    return bucket_id


def nte_targets(project_id):
    return rows(
        """
        SELECT
          'sp:' || sp.id AS target_key,
          'Subproject' AS target_type,
          sp.id AS subproject_id,
          NULL AS change_order_id,
          sp.job_number,
          sp.code,
          sp.name,
          sp.pricing_type,
          p.customer,
          p.name AS project_name
        FROM subprojects sp
        JOIN projects p ON p.id = sp.project_id
        WHERE sp.project_id = ? AND COALESCE(sp.pricing_type, 'Fixed') = 'T&M NTE'
        UNION ALL
        SELECT
          'co:' || co.id AS target_key,
          COALESCE(co.order_type, 'Change Order') AS target_type,
          co.subproject_id,
          co.id AS change_order_id,
          co.job_number,
          co.co_number AS code,
          co.title AS name,
          co.pricing_type,
          p.customer,
          p.name AS project_name
        FROM change_orders co
        JOIN projects p ON p.id = co.project_id
        WHERE co.project_id = ? AND COALESCE(co.pricing_type, 'Fixed') = 'T&M NTE'
        ORDER BY target_type, job_number, code
        """,
        (project_id, project_id),
    )


def customer_dashboard_summary(project_id):
    project_id = int(project_id) if project_id else None
    empty_summary = {"sales_total": 0, "labor_hours": 0, "ticket_count": 0, "last_ticket_date": ""}
    if not project_id:
        return {"project": None, "targets": [], "tickets": [], "summary": empty_summary}
    project = one("SELECT id, project_code, name, customer, location, customer_po FROM projects WHERE id = ?", (project_id,))
    subproject_targets = rows(
        """
        SELECT
          'Subproject' AS target_type,
          sp.id AS target_id,
          sp.id AS subproject_id,
          NULL AS change_order_id,
          sp.job_number,
          sp.code,
          sp.name AS title,
          sp.pricing_type,
          COALESCE(SUM(CASE WHEN cr.source IN ('Field Wise', 'Field Wise PDF') THEN cr.sales_amount ELSE 0 END), 0) AS sales_total,
          COALESCE(SUM(CASE WHEN cr.source IN ('Field Wise', 'Field Wise PDF') AND cr.cost_type = 'Labor' THEN cr.qty ELSE 0 END), 0) AS labor_hours,
          COUNT(DISTINCT CASE WHEN cr.source IN ('Field Wise', 'Field Wise PDF') THEN cr.ticket_or_invoice END) AS ticket_count,
          MAX(CASE WHEN cr.source IN ('Field Wise', 'Field Wise PDF') THEN cr.record_date ELSE NULL END) AS last_ticket_date
        FROM subprojects sp
        LEFT JOIN cost_records cr ON cr.subproject_id = sp.id AND cr.change_order_id IS NULL
        WHERE sp.project_id = ?
          AND COALESCE(sp.pricing_type, 'Fixed') = 'T&M NTE'
        GROUP BY sp.id
        ORDER BY sp.job_number, sp.code, sp.name
        """,
        (project_id,),
    )
    change_order_targets = rows(
        """
        SELECT
          COALESCE(co.order_type, 'Change Order') AS target_type,
          co.id AS target_id,
          co.subproject_id,
          co.id AS change_order_id,
          co.job_number,
          co.co_number AS code,
          co.title,
          co.pricing_type,
          COALESCE(sp.job_number, '') AS parent_job_number,
          COALESCE(sp.code, '') AS parent_code,
          COALESCE(sp.name, '') AS parent_name,
          COALESCE(SUM(CASE WHEN cr.source IN ('Field Wise', 'Field Wise PDF') THEN cr.sales_amount ELSE 0 END), 0) AS sales_total,
          COALESCE(SUM(CASE WHEN cr.source IN ('Field Wise', 'Field Wise PDF') AND cr.cost_type = 'Labor' THEN cr.qty ELSE 0 END), 0) AS labor_hours,
          COUNT(DISTINCT CASE WHEN cr.source IN ('Field Wise', 'Field Wise PDF') THEN cr.ticket_or_invoice END) AS ticket_count,
          MAX(CASE WHEN cr.source IN ('Field Wise', 'Field Wise PDF') THEN cr.record_date ELSE NULL END) AS last_ticket_date
        FROM change_orders co
        LEFT JOIN subprojects sp ON sp.id = co.subproject_id
        LEFT JOIN cost_records cr ON cr.change_order_id = co.id
        WHERE co.project_id = ?
          AND COALESCE(co.pricing_type, 'Fixed') = 'T&M NTE'
        GROUP BY co.id
        ORDER BY co.job_number, co.co_number, co.title
        """,
        (project_id,),
    )
    targets = subproject_targets + change_order_targets
    tickets = rows(
        """
        SELECT
          cr.ticket_or_invoice,
          cr.record_date,
          cr.status,
          CASE WHEN cr.change_order_id IS NOT NULL THEN COALESCE(co.order_type, 'Change Order') ELSE 'Subproject' END AS target_type,
          COALESCE(co.job_number, sp.job_number, '') AS job_number,
          COALESCE(co.co_number, sp.code, '') AS code,
          COALESCE(co.title, sp.name, '') AS title,
          COALESCE(SUM(cr.sales_amount), 0) AS sales_total,
          COALESCE(SUM(CASE WHEN cr.cost_type = 'Labor' THEN cr.qty ELSE 0 END), 0) AS labor_hours
        FROM cost_records cr
        LEFT JOIN subprojects sp ON sp.id = cr.subproject_id
        LEFT JOIN change_orders co ON co.id = cr.change_order_id
        WHERE cr.project_id = ?
          AND cr.source IN ('Field Wise', 'Field Wise PDF')
          AND (
            (cr.change_order_id IS NULL AND COALESCE(sp.pricing_type, 'Fixed') = 'T&M NTE')
            OR
            (cr.change_order_id IS NOT NULL AND COALESCE(co.pricing_type, 'Fixed') = 'T&M NTE')
          )
        GROUP BY cr.ticket_or_invoice, cr.record_date, cr.status, cr.change_order_id, cr.subproject_id
        ORDER BY cr.record_date DESC, cr.ticket_or_invoice DESC
        """,
        (project_id,),
    )
    summary = {
        "sales_total": sum(money(t.get("sales_total")) for t in targets),
        "labor_hours": sum(money(t.get("labor_hours")) for t in targets),
        "ticket_count": sum(int(t.get("ticket_count") or 0) for t in targets),
        "last_ticket_date": max([str(t.get("last_ticket_date") or "") for t in targets] or [""]),
    }
    return {"project": project, "targets": targets, "tickets": tickets, "summary": summary}


def nte_completion_by_bucket(project_id):
    completions = {}
    for row in rows(
        """
        SELECT c.*
        FROM nte_completion_updates c
        JOIN (
          SELECT bucket_id, MAX(COALESCE(report_date, '') || '|' || created_at || '|' || printf('%010d', id)) AS latest_key
          FROM nte_completion_updates
          WHERE project_id = ?
            AND bucket_id IS NOT NULL
          GROUP BY bucket_id
        ) latest ON latest.bucket_id = c.bucket_id
          AND latest.latest_key = COALESCE(c.report_date, '') || '|' || c.created_at || '|' || printf('%010d', c.id)
        WHERE c.project_id = ?
        """,
        (project_id, project_id),
    ):
        completions[row["bucket_id"]] = dict(row)
    return completions


def nte_summary(project_id, subproject_id=None, change_order_id=None, seed_defaults=False, all_targets=False):
    project_id = int(project_id) if project_id else None
    subproject_id = int(subproject_id) if subproject_id else None
    change_order_id = int(change_order_id) if change_order_id else None
    with db() as con:
        if seed_defaults:
            ensure_nte_defaults(con, project_id, subproject_id, change_order_id)
        target_filter = "" if all_targets else "AND COALESCE(subproject_id, 0) = COALESCE(?, 0) AND COALESCE(change_order_id, 0) = COALESCE(?, 0)"
        target_params = () if all_targets else (subproject_id or None, change_order_id or None)
        bucket_rows = [dict(r) for r in con.execute(
            f"""
            SELECT *
            FROM nte_buckets
            WHERE project_id = ?
              {target_filter}
              AND COALESCE(active, 1) = 1
            ORDER BY sort_order, name
            """,
            (project_id, *target_params),
        ).fetchall()]
        sub_rows = [dict(r) for r in con.execute(
            f"""
            SELECT sb.*
            FROM nte_subbuckets sb
            JOIN nte_buckets b ON b.id = sb.bucket_id
            WHERE b.project_id = ?
              {target_filter.replace("subproject_id", "b.subproject_id").replace("change_order_id", "b.change_order_id")}
              AND COALESCE(sb.active, 1) = 1
            ORDER BY sb.sort_order, sb.name
            """,
            (project_id, *target_params),
        ).fetchall()]
        additions = [dict(r) for r in con.execute(
            f"""
            SELECT a.*, b.name AS bucket_name, sb.name AS subbucket_name
            FROM nte_bucket_additions a
            JOIN nte_buckets b ON b.id = a.bucket_id
            LEFT JOIN nte_subbuckets sb ON sb.id = a.subbucket_id
            WHERE a.project_id = ?
              {target_filter.replace("subproject_id", "b.subproject_id").replace("change_order_id", "b.change_order_id")}
            ORDER BY a.created_at DESC, a.id DESC
            """,
            (project_id, *target_params),
        ).fetchall()]
        reallocations = [dict(r) for r in con.execute(
            f"""
            SELECT r.*, from_b.name AS from_bucket_name, to_b.name AS to_bucket_name
            FROM nte_bucket_reallocations r
            JOIN nte_buckets from_b ON from_b.id = r.from_bucket_id
            JOIN nte_buckets to_b ON to_b.id = r.to_bucket_id
            WHERE r.project_id = ?
              {target_filter.replace("subproject_id", "from_b.subproject_id").replace("change_order_id", "from_b.change_order_id")}
            ORDER BY r.created_at DESC, r.id DESC
            """,
            (project_id, *target_params),
        ).fetchall()]
        panel_deliverables = [dict(r) for r in con.execute(
            """
            SELECT p.*, b.name AS bucket_name
            FROM nte_panel_deliverables p
            LEFT JOIN nte_buckets b ON b.id = p.bucket_id
            WHERE p.project_id = ?
              AND COALESCE(p.active, 1) = 1
            ORDER BY COALESCE(b.sort_order, 9999), b.name, p.sort_order, p.name, p.id
            """,
            (project_id,),
        ).fetchall()]
        actuals = {
            r["nte_subbucket_id"]: money(r["actual"])
            for r in con.execute(
                """
                SELECT
                  nte_subbucket_id,
                  COALESCE(SUM(
                    CASE
                      WHEN COALESCE(sales_amount, 0) <> 0 THEN sales_amount
                      ELSE amount
                    END
                  ), 0) AS actual
                FROM cost_records
                WHERE project_id = ? AND nte_subbucket_id IS NOT NULL
                GROUP BY nte_subbucket_id
                """,
                (project_id,),
            ).fetchall()
        }
        labor_hours_actuals = {
            r["nte_subbucket_id"]: money(r["actual_hours"])
            for r in con.execute(
                """
                SELECT nte_subbucket_id, COALESCE(SUM(qty), 0) AS actual_hours
                FROM cost_records
                WHERE project_id = ? AND nte_subbucket_id IS NOT NULL AND cost_type = 'Labor'
                GROUP BY nte_subbucket_id
                """,
                (project_id,),
            ).fetchall()
        }
        unproductive_labor_hours = {
            r["nte_subbucket_id"]: money(r["unproductive_hours"])
            for r in con.execute(
                """
                SELECT nte_subbucket_id, COALESCE(SUM(qty), 0) AS unproductive_hours
                FROM cost_records
                WHERE project_id = ?
                  AND nte_subbucket_id IS NOT NULL
                  AND cost_type = 'Labor'
                  AND COALESCE(nte_unproductive_time, 0) = 1
                GROUP BY nte_subbucket_id
                """,
                (project_id,),
            ).fetchall()
        }
    additions_by_sub = {}
    additions_by_bucket = {}
    pending_bucket_allocations = {}
    for addition in additions:
        if addition.get("status") == "Approved":
            additions_by_bucket[addition["bucket_id"]] = additions_by_bucket.get(addition["bucket_id"], 0) + money(addition["amount"])
            if addition.get("subbucket_id"):
                additions_by_sub[addition["subbucket_id"]] = additions_by_sub.get(addition["subbucket_id"], 0) + money(addition["amount"])
            else:
                pending_bucket_allocations.setdefault(addition["bucket_id"], {"Labor": 0, "Material": 0, "Equipment": 0})
                pending_bucket_allocations[addition["bucket_id"]]["Labor"] += money(addition.get("labor_amount"))
                pending_bucket_allocations[addition["bucket_id"]]["Material"] += money(addition.get("material_amount"))
                pending_bucket_allocations[addition["bucket_id"]]["Equipment"] += money(addition.get("equipment_amount"))
    reallocations_by_bucket = {}
    pending_reallocation_allocations = {}
    for reallocation in reallocations:
        if reallocation.get("status") == "Approved":
            from_bucket_id = reallocation["from_bucket_id"]
            to_bucket_id = reallocation["to_bucket_id"]
            amount = money(reallocation["amount"])
            labor_amount = money(reallocation.get("labor_amount"))
            material_amount = money(reallocation.get("material_amount"))
            equipment_amount = money(reallocation.get("equipment_amount"))
            reallocations_by_bucket[from_bucket_id] = reallocations_by_bucket.get(from_bucket_id, 0) - amount
            reallocations_by_bucket[to_bucket_id] = reallocations_by_bucket.get(to_bucket_id, 0) + amount
            pending_reallocation_allocations.setdefault(from_bucket_id, {"Labor": 0, "Material": 0, "Equipment": 0})
            pending_reallocation_allocations.setdefault(to_bucket_id, {"Labor": 0, "Material": 0, "Equipment": 0})
            pending_reallocation_allocations[from_bucket_id]["Labor"] -= labor_amount
            pending_reallocation_allocations[from_bucket_id]["Material"] -= material_amount
            pending_reallocation_allocations[from_bucket_id]["Equipment"] -= equipment_amount
            pending_reallocation_allocations[to_bucket_id]["Labor"] += labor_amount
            pending_reallocation_allocations[to_bucket_id]["Material"] += material_amount
            pending_reallocation_allocations[to_bucket_id]["Equipment"] += equipment_amount
    allocation_targets = {}
    for sub in sub_rows:
        target_map = allocation_targets.setdefault(sub["bucket_id"], {})
        cost_type = str(sub.get("cost_type") or "")
        if cost_type == "Labor" and "Labor" not in target_map:
            target_map["Labor"] = sub["id"]
        elif cost_type in ("Material", "Field Ticket Material") and "Material" not in target_map:
            target_map["Material"] = sub["id"]
        elif cost_type == "Equipment" and "Equipment" not in target_map:
            target_map["Equipment"] = sub["id"]
    by_bucket = {b["id"]: {**b, "subbuckets": [], "original_budget": 0, "approved_additions": 0, "approved_reallocations": 0, "current_budget": 0, "actual_cost": 0, "remaining": 0, "labor_hours_budget": 0, "labor_hours_used": 0, "labor_hours_remaining": 0, "unproductive_labor_hours": 0} for b in bucket_rows}
    for sub in sub_rows:
        approved = additions_by_sub.get(sub["id"], 0)
        bucket_allocations = pending_bucket_allocations.get(sub["bucket_id"], {})
        reallocated = 0
        reallocation_allocations = pending_reallocation_allocations.get(sub["bucket_id"], {})
        target_map = allocation_targets.get(sub["bucket_id"], {})
        if target_map.get("Labor") == sub["id"]:
            approved += bucket_allocations.get("Labor", 0)
            reallocated += reallocation_allocations.get("Labor", 0)
        if target_map.get("Material") == sub["id"]:
            approved += bucket_allocations.get("Material", 0)
            reallocated += reallocation_allocations.get("Material", 0)
        if target_map.get("Equipment") == sub["id"]:
            approved += bucket_allocations.get("Equipment", 0)
            reallocated += reallocation_allocations.get("Equipment", 0)
        actual = actuals.get(sub["id"], 0)
        labor_hours_budget = money(sub.get("labor_hours_budget")) if sub.get("cost_type") == "Labor" else 0
        labor_hours_used = labor_hours_actuals.get(sub["id"], 0) if sub.get("cost_type") == "Labor" else 0
        unproductive_hours = unproductive_labor_hours.get(sub["id"], 0) if sub.get("cost_type") == "Labor" else 0
        current = money(sub["original_budget"]) + approved + reallocated
        item = {**sub, "approved_additions": approved, "approved_reallocations": reallocated, "current_budget": current, "actual_cost": actual, "remaining": current - actual, "labor_hours_budget": labor_hours_budget, "labor_hours_used": labor_hours_used, "labor_hours_remaining": labor_hours_budget - labor_hours_used, "unproductive_labor_hours": unproductive_hours}
        bucket = by_bucket.get(sub["bucket_id"])
        if bucket:
            bucket["subbuckets"].append(item)
            bucket["original_budget"] += money(sub["original_budget"])
            bucket["approved_additions"] += approved
            bucket["approved_reallocations"] += reallocated
            bucket["actual_cost"] += actual
            bucket["labor_hours_budget"] += labor_hours_budget
            bucket["labor_hours_used"] += labor_hours_used
            bucket["unproductive_labor_hours"] += unproductive_hours
    completions = nte_completion_by_bucket(project_id)
    for bucket in by_bucket.values():
        bucket["approved_additions"] = max(bucket["approved_additions"], additions_by_bucket.get(bucket["id"], bucket["approved_additions"]))
        if bucket["id"] in reallocations_by_bucket:
            bucket["approved_reallocations"] = reallocations_by_bucket[bucket["id"]]
        bucket["current_budget"] = bucket["original_budget"] + bucket["approved_additions"] + bucket["approved_reallocations"]
        bucket["remaining"] = bucket["current_budget"] - bucket["actual_cost"]
        bucket["labor_hours_remaining"] = bucket["labor_hours_budget"] - bucket["labor_hours_used"]
        bucket["completion"] = completions.get(bucket["id"], {"completion_percent": 0, "report_date": "", "notes": "", "created_by_username": "", "created_at": ""})
        completion_percent = money(bucket["completion"].get("completion_percent"))
        actual_cost = money(bucket["actual_cost"])
        current_budget = money(bucket["current_budget"])
        if completion_percent > 0:
            estimated_at_completion = actual_cost / (completion_percent / 100)
            estimated_to_complete = max(0, estimated_at_completion - actual_cost)
            estimated_variance = current_budget - estimated_at_completion
        else:
            estimated_at_completion = 0
            estimated_to_complete = 0
            estimated_variance = 0
        bucket["estimated_cost_at_completion"] = estimated_at_completion
        bucket["estimated_cost_to_complete"] = estimated_to_complete
        bucket["estimated_completion_variance"] = estimated_variance
        bucket["estimated_completion_status"] = "No field completion entered" if completion_percent <= 0 else ("Projected under budget" if estimated_variance >= 0 else "Projected over budget")
        for sub in bucket.get("subbuckets", []):
            sub_actual = money(sub.get("actual_cost"))
            sub_budget = money(sub.get("current_budget"))
            if completion_percent > 0:
                sub_estimated_at_completion = sub_actual / (completion_percent / 100)
                sub_estimated_to_complete = max(0, sub_estimated_at_completion - sub_actual)
                sub_estimated_variance = sub_budget - sub_estimated_at_completion
            else:
                sub_estimated_at_completion = 0
                sub_estimated_to_complete = 0
                sub_estimated_variance = 0
            sub["estimated_cost_at_completion"] = sub_estimated_at_completion
            sub["estimated_cost_to_complete"] = sub_estimated_to_complete
            sub["estimated_completion_variance"] = sub_estimated_variance
            sub["estimated_completion_status"] = "No field completion entered" if completion_percent <= 0 else ("Projected under budget" if sub_estimated_variance >= 0 else "Projected over budget")
    for panel in panel_deliverables:
        total_panels = money(panel.get("total_panels"))
        completed_panels = min(total_panels, money(panel.get("completed_panels"))) if total_panels > 0 else money(panel.get("completed_panels"))
        panel["total_panels"] = total_panels
        panel["completed_panels"] = completed_panels
        panel["remaining_panels"] = max(0, total_panels - completed_panels)
        panel["completion_percent"] = round((completed_panels / total_panels) * 100, 1) if total_panels > 0 else 0
    return {"buckets": list(by_bucket.values()), "additions": additions, "reallocations": reallocations, "panel_deliverables": panel_deliverables}


def nte_rule_suggestion(con, record):
    haystacks = {
        "item": str(record.get("item") or "").lower(),
        "description": str(record.get("description") or "").lower(),
        "item_description": " ".join(str(record.get(k) or "") for k in ("item", "description")).lower(),
    }
    rules = con.execute(
        """
        SELECT r.*, sb.name AS subbucket_name, b.name AS bucket_name
        FROM nte_coding_rules r
        JOIN nte_subbuckets sb ON sb.id = r.subbucket_id
        JOIN nte_buckets b ON b.id = sb.bucket_id
        WHERE r.project_id = ? AND COALESCE(r.active, 1) = 1
        ORDER BY r.auto_apply DESC, r.approval_count DESC, LENGTH(r.match_text) DESC
        """,
        (record.get("project_id"),),
    ).fetchall()
    for rule in rules:
        if rule["cost_type"] and record.get("cost_type") and rule["cost_type"] != record.get("cost_type"):
            continue
        match_text = str(rule["match_text"] or "").strip().lower()
        if not match_text:
            continue
        field = rule["match_field"] if rule["match_field"] in haystacks else "item_description"
        if match_text in haystacks[field]:
            return dict(rule)
    return None


def default_nte_subbucket_for_cost(con, record):
    cost_type = str(record.get("cost_type") or "").strip()
    if cost_type == "Labor":
        accepted_types = ("Labor",)
        preferred_name = "Labor"
    elif cost_type in ("Field Ticket Material", "Material"):
        accepted_types = ("Material", "Field Ticket Material")
        preferred_name = "Material"
    elif cost_type == "Equipment":
        accepted_types = ("Equipment",)
        preferred_name = "Equipment"
    else:
        return None
    placeholders = ",".join(["?"] * len(accepted_types))
    return con.execute(
        f"""
        SELECT sb.id, sb.name AS subbucket_name, b.name AS bucket_name
        FROM nte_subbuckets sb
        JOIN nte_buckets b ON b.id = sb.bucket_id
        WHERE b.project_id = ?
          AND COALESCE(b.subproject_id, 0) = COALESCE(?, 0)
          AND COALESCE(b.change_order_id, 0) = COALESCE(?, 0)
          AND COALESCE(sb.active, 1) = 1
          AND sb.cost_type IN ({placeholders})
        ORDER BY
          CASE WHEN LOWER(sb.name) = LOWER(?) THEN 0 ELSE 1 END,
          sb.sort_order,
          sb.name
        LIMIT 1
        """,
        (
            record.get("project_id"),
            record.get("subproject_id") or None,
            record.get("change_order_id") or None,
            *accepted_types,
            preferred_name,
        ),
    ).fetchone()


